  "Evde kaldın, erkenden yattın. Sıkıcı ama profesyonel.": "Te quedaste en casa y te acostaste temprano. Aburrido pero profesional.",
  "Gece kontrolden çıktı: bir kavga videosu sızdı. Magazin manşetlerindesin. Popülerlik -4, sağlık -8.": "La noche se descontroló: se filtró un video de una pelea. Estás en los titulares de la prensa rosa. Popularidad -4, salud -8.",
  "Ünlülerle fotoğrafların her yerde. Yeni bir kitleye ulaştın. Popülerlik +3.": "Tus fotos con famosos están por todas partes. Llegaste a un público nuevo. Popularidad +3.",
