  "— {0}. RAUNT — Sen: {1}": "— ASALTO {0} — Tú: {1}",
  "🧠 {0} bu hamleyi bekliyordu. Aynı oyunu {1}. kez oynamak seni öngörülebilir yapıyor.": "🧠 {0} esperaba ese movimiento. Repetir la misma jugada ({1} veces ya) te hace predecible.",
