  "🔥 {0} yağmur gibi yumruk indiriyor, {1} karşılık veremiyor, hakem araya giriyor! TKO!": "🔥 ¡{0} llueve golpes, {1} no responde, el árbitro interviene! ¡TKO!",
  "😱 {0} umutsuz bir kontra savurdu ve TAM İSABET! Durum tersine döndü!": "😱 ¡{0} lanzó un contragolpe desesperado y CONECTÓ DE LLENO! ¡Se dio vuelta la tortilla!",
  "{0} bir şekilde ayakta kaldı, zili bekliyor. Sen de çok yoruldun.": "{0} de algún modo sigue de pie, esperando la campana. Tú también estás agotado.",
  "🎯 {0} hedef seçerek vuruyor, sağ-sol-sağ… hakem yeter diyor! TKO!": "🎯 {0} elige sus golpes, derecha-izquierda-derecha… ¡el árbitro ya vio suficiente! ¡TKO!",
  "{0} kontrollü vuruşlarla puan topluyor, rakip toparlanmaya çalışıyor.": "{0} suma con golpes controlados mientras su rival intenta recuperarse.",
  "{0} yere indirmek için daldı ama rakip son gücüyle savundu. Fırsat kaçtı.": "{0} buscó el derribo pero el rival se defendió con lo que le quedaba. La oportunidad se fue.",
  "🔨 {0} yerde mount aldı, ground and pound yağdırıyor, hakem durdurdu! TKO!": "🔨 ¡{0} tomó la montada en el suelo, lloviendo ground and pound, el árbitro lo detuvo! ¡TKO!",
  "🔒 {0} sersem rakibin sırtını aldı ve {1} ile tap attırdı!": "🔒 ¡{0} tomó la espalda del rival aturdido y lo hizo rendirse con un {1}!",
  "{0} yerde ağır vuruyor ama {1} bir şekilde hayatta kalıyor.": "{0} conecta golpes pesados en el suelo, pero {1} de algún modo sobrevive.",
