  "Rakibine sarıldın, kafanı yasladın. Saniyeler geçiyor… toparlanıyorsun.": "Te amarraste en el clinch y apoyaste la cabeza. Pasan los segundos… te estás recuperando.",
  "Ayakların seni taşıdı. Kafes boyunca dönüp mesafe açtın, kafan netleşiyor.": "Tus piernas te sostuvieron. Rodeaste la jaula, hiciste distancia y se te despeja la cabeza.",
