  "💀 {0} yumruk yağdırıyor, kendini savunamıyorsun. Hakem durdurdu. TKO.": "💀 {0} llueve golpes, no puedes defenderte. El árbitro lo detuvo. TKO.",
  "Ağır darbeler aldın ama ayaktasın. Zil seni kurtarmak zorunda.": "Recibiste golpes duros pero sigues de pie. La campana tiene que salvarte.",
  "🔒 {0} {1} kilidini sonuna kadar sıktı… {2} TAP ATTI!": "🔒 {0} apretó el {1} a fondo… ¡{2} SE RINDIÓ!",
  "{0} son anda {1} kilidinden sıyrıldı ve ayağa kalktı!": "¡{0} se escapó del {1} en el último segundo y se levantó!",
  "{0} riske girmiyor, üstte kalıp dirsek ve yumrukla puan topluyor.": "{0} va a lo seguro, se queda arriba y suma con codos y golpes.",
