  "Yeni bir silah geliştiriyoruz. Maç gecesi göreceksiniz… 🤫": "Estamos construyendo un arma nueva. La verán la noche de la pelea… 🤫",
  "Kilo kontrolde, zihin net. {rakip} gelsin.": "El peso va bien, la mente clara. Que venga {rakip}.",
  "{salon}’da bir gece daha. Işıklar sönene kadar buradayım. 💡": "Otra noche en {salon}. Aquí sigo hasta que se apaguen las luces. 💡",
  "Bugün 10 raunt spar. Yoruldum ama durmadım.": "Hoy 10 asaltos de sparring. Cansado, pero no paré.",
  "Video analiz günü: {rakip}’in her hareketini ezberliyorum. 🎬": "Día de video: memorizando cada movimiento de {rakip}. 🎬",
  "Buz banyosu, masaj, uyku. Savaşçı dinlenmeyi de bilir. 🧊": "Baño de hielo, masaje, dormir. Un guerrero también sabe descansar. 🧊",
  "Kamp güncellemesi: sağlıklı, aç ve tehlikeli. 🐺": "Parte del campamento: sano, hambriento y peligroso. 🐺",
  "{rakip} kafeste beni görünce kaçacak yer arayacak. 😂": "{rakip} buscará por dónde escapar cuando me vea en la jaula. 😂",
  "{rakip}, sosyal medyada çok cesursun. Kafeste görüşürüz.": "{rakip}, eres muy valiente en redes. Nos vemos en la jaula.",
  "Bu gece {rakip} uyumayacak. Çünkü maç gecesi uyutacağım. 💤": "{rakip} no dormirá esta noche. Porque lo dormiré yo la noche de la pelea. 💤",
  "{rakip} diye bir dövüşçü yok, sadece bir sonraki kurbanım var.": "No existe un peleador llamado {rakip}, solo mi próxima víctima.",
  "{rakip} hayranları, şimdiden mendilleri hazırlayın. 🤧": "Fans de {rakip}, preparen los pañuelos. 🤧",
  "{rakip}’in çenesi o kadar dayanıklı değil, herkes biliyor.": "El mentón de {rakip} no es tan duro, todos lo saben.",
  "Kamera önünde herkes aslan. Kafes kapısı kapanınca görürüz {rakip}.": "Todos son leones frente a la cámara. Veremos cuando se cierre la jaula, {rakip}.",
  "{rakip}, hazır ol. Kariyerinin en kötü gecesi yaklaşıyor.": "{rakip}, prepárate. Se acerca la peor noche de tu carrera.",
  "Söylediklerimin arkasındayım: {rakip} bu maçı bitiremeyecek.": "Mantengo lo dicho: {rakip} no terminará esta pelea.",
  "{sampiyon}, kemerini hazırla. Geliyorum. 🏆": "{sampiyon}, prepara tu cinturón. Voy por él. 🏆",
  "{sampiyon} benden kaçıyor. {org}, bu maçı yapın!": "{sampiyon} me está huyendo. ¡{org}, haz esta pelea!",
  "Sıklette kimse benimle dövüşmek istemiyor. Sıradaki kim? 👀": "Nadie en la categoría quiere pelear conmigo. ¿Quién sigue? 👀",
  "{sampiyon}, tahtında rahat oturma. Sıra bende.": "{sampiyon}, no te acomodes en ese trono. Soy el siguiente.",
  "İlk 5’e giren herkese açık davet: kafeste görüşelim.": "Invitación abierta a cualquiera del top 5: nos vemos en la jaula.",
  "{org}, bana bir şampiyonluk maçı borçlusunuz. Hak ettim.": "{org}, me debes una oportunidad por el título. Me la gané.",
  "Adımı unutmayın. Yakında o kemer bende olacak.": "Recuerden mi nombre. Pronto ese cinturón será mío.",
  "{rakip} gerçek bir savaşçı. Maç gecesi en iyi hâlimizle karşılaşacağız. 🤝": "{rakip} es un verdadero guerrero. Nos veremos en nuestra mejor versión la noche de la pelea. 🤝",
  "Rakibime saygım sonsuz. Ama kazanan ben olacağım.": "Respeto infinito para mi rival. Pero el que ganará seré yo.",
  "{hoca} ve tüm takımıma teşekkürler. Bu yol tek başına yürünmez.": "Gracias a {hoca} y a todo mi equipo. Nadie recorre este camino solo.",
  "Sıklette herkes çok çalışıyor. Bu yüzden bu spor güzel.": "Todos en la categoría trabajan duro. Eso es lo que hace hermoso este deporte.",
  "Yenildiğim her maç bana bir şey öğretti. Hepsine minnettarım.": "Cada derrota me enseñó algo. Agradezco todas.",
  "Rakiplerime saygı, taraftarlara sevgi. Gerisi kafeste. 🙏": "Respeto a mis rivales, amor a los fans. Lo demás pasa en la jaula. 🙏",
  "{takipci} kişi! İnanılmaz. Her birinize teşekkür ederim. ❤️": "¡{takipci} personas! Increíble. Gracias a cada uno de ustedes. ❤️",
  "Maç gecesi tribünler yine bizim olsun! Kim geliyor? 🙌": "¡Adueñémonos otra vez de las gradas la noche de la pelea! ¿Quién viene? 🙌",
  "Bir taraftarım bugün bana el yazısı mektup verdi. Ağladım. 🥹": "Hoy un fan me dio una carta escrita a mano. Lloré. 🥹",
  "{memleket}, bu zafer senin için!": "¡{memleket}, esta victoria es para ti!",
  "Sorularınızı yazın, en iyilerini bu akşam cevaplayacağım. 👇": "Dejen sus preguntas, esta noche respondo las mejores. 👇",
  "Bu yolculukta yanımda olan herkese: sizin sayenizde buradayım.": "A todos los que me han acompañado en este viaje: estoy aquí gracias a ustedes.",
  "Kimse sana inanmasa da sen kendine inan. 💯": "Cree en ti incluso cuando nadie más lo haga. 💯",
  "Ter antrenmanda akar ki kan kafeste akmasın.": "Suda en el entrenamiento para no sangrar en la jaula.",
  "Düştüğün yer değil, kalktığın yer seni tanımlar.": "No te define dónde caes, sino dónde te levantas.",
  "Bugün acı, yarın zafer. 🔥": "Dolor hoy, victoria mañana. 🔥",
  "Yetenek başlatır, disiplin bitirir.": "El talento empieza, la disciplina termina.",
  "Her sabah aynı soru: bugün dünden daha iyi miyim?": "La misma pregunta cada mañana: ¿soy mejor que ayer?",
  "Kolay olsaydı herkes şampiyon olurdu.": "Si fuera fácil, todos serían campeones.",
  "Bugün dinlenme günü. Ailemle kahvaltı. Savaşçılar da insan. ❤️": "Hoy día de descanso. Desayuno en familia. Los guerreros también son humanos. ❤️",
  "Yeni tatlı yasak listesi: hepsi. 🍰❌": "Nueva lista de postres prohibidos: todos. 🍰❌",
  "Bir kahve, biraz müzik, sonra tekrar salon. ☕🎧": "Un café, algo de música y de vuelta al gimnasio. ☕🎧",
  "Hayatımda iki şey var: kafes ve sevdiklerim.": "Dos cosas en mi vida: la jaula y mis seres queridos.",
  "{sponsor} ile yola devam! Teşekkürler ekip. 🤝": "¡Sigo rodando con {sponsor}! Gracias, equipo. 🤝",
  "Maç gecesi {sponsor} logosuyla kafesteyim. 💪": "En la jaula la noche de la pelea con el logo de {sponsor}. 💪",
  "{sponsor} ailesine katılmak gurur verici. Birlikte zirveye!": "Orgulloso de unirme a la familia {sponsor}. ¡Juntos a la cima!",
  "Soru: sıradaki maçımı nakavtla mı bitireyim, submission ile mi? 👇": "Pregunta: ¿termino mi próxima pelea por nocaut o por sumisión? 👇",
  "Sizce sıklette en tehlikeli isim kim? Yorumlara yazın.": "¿Quién creen que es el nombre más peligroso de la categoría? Comenten.",
  "Tüm zamanların en iyisi kim sizce? Tartışalım. 🐐": "¿Quién es el más grande de todos los tiempos? Debatamos. 🐐",
  "Maç gecesi hangi şarkıyla çıkayım? Önerilere açığım. 🎵": "¿Con qué canción salgo la noche de la pelea? Acepto sugerencias. 🎵",
  "Hangi rakiple dövüşmemi istersiniz? En çok beğenilen yorumu {org}’a ileteceğim.": "¿Contra quién quieren que pelee? Le paso a {org} el comentario con más likes.",
