  "{ph} mi? {org}’da bana verilen en kolay maç bu. {hafta} hafta sonra görürüz.": "¿{ph}? La pelea más fácil que me ha dado {org}. Nos vemos en {hafta} semanas.",
  "{ph} kafeste görüşürüz. Hastane masrafını ben öderim, merak etme.": "Nos vemos en la jaula, {ph}. La cuenta del hospital la pago yo, tranquilo.",
