  "Kamp bitti. {ph}, iyi bir savaş olsun. 🤝": "Campamento terminado. {ph}, tengamos una buena guerra. 🤝",
  "{ph} söylemiştim. Sıradaki! 👋": "Te lo dije, {ph}. ¡El siguiente! 👋",
  "Bu gece bir şey kanıtladım. {ph}, iyi dövüştün ama yeterli değildi.": "Esta noche demostré algo. {ph}, peleaste bien, pero no bastó.",
  "Kemer yolu devam ediyor. {ph} sadece bir basamaktı.": "El camino al cinturón sigue. {ph} fue solo un escalón.",
  "{ph} bu gece daha iyiydi. Tebrikler şampiyon adayı. Geri döneceğim.": "{ph} fue mejor esta noche. Felicidades, futuro campeón. Volveré.",
  "Ders aldım. {ph} gerçek bir savaşçı. 🤝": "Lección aprendida. {ph} es un verdadero guerrero. 🤝",
