  "♥ BPM": "♥ LPM",
  "Karakterini Nasıl Kurarsın?": "¿Cómo creas a tu personaje?",
  "🌍 Uyruk: Antrenman imkânı başlangıç istatistiklerini, taraftar desteği başlangıç popülerliğini belirler. İlk salonun ve hocan da ülkene göre gelir.": "🌍 Nacionalidad: las opciones de entrenamiento fijan tus estadísticas iniciales y el apoyo de los fans tu popularidad inicial. Tu primer gimnasio y entrenador también dependen de tu país.",
  "🎂 Yaş (18-30): Genç başlarsan ham ama hızlı gelişirsin (×1.3). Yaşlı başlarsan güçlü başlarsın ama 32’den sonra hız ve çene düşmeye başlar. 41’de emeklilik kaçınılmazdır.": "🎂 Edad (18-30): si empiezas joven estás verde pero creces rápido (×1,3). Si empiezas mayor eres más fuerte, pero tras los 32 la velocidad y el mentón empiezan a bajar. El retiro es inevitable a los 41.",
  "⚖️ Sıklet: Hafif sıkletler hızlı ve dayanıklıdır, ağır sıkletler sert vurur ama çabuk yorulur.": "⚖️ Categoría: los pesos ligeros son rápidos y resistentes; los pesados pegan fuerte pero se cansan rápido.",
  "🥋 Branş: En önemli seçim. Güçlü ve zayıf yönlerini, dolayısıyla nasıl dövüşeceğini belirler.": "🥋 Base: la elección más importante. Define tus fortalezas y debilidades, y con ello cómo peleas.",
  "📖 Hikâye: Kendin yazabilir ya da oyuna yazdırabilirsin.": "📖 Historia: escríbela tú o deja que la escriba el juego.",
  "🎲 Zar: Son adımda istatistiklerin zarla belirlenir. Beğenmezsen 2 kez yeniden atabilirsin.": "🎲 Dados: en el último paso se tiran tus estadísticas. ¿No te gustan? Puedes volver a tirar dos veces.",
  "Gelişim Puanı": "Puntos de habilidad",
  "Kariyere 3 puanla başlarsın. Her antrenman kampı 1-3 puan verir (yoğunluk, yaş, kamp yeri, hoca ve kadro kalitesine bağlı). Kampın odak alanı ayrıca +1-3 gelişir.": "Empiezas tu carrera con 3 puntos. Cada campamento da 1-3 puntos (según intensidad, edad, sede, entrenador y calidad del equipo). El área de enfoque del campamento también mejora +1-3.",
  "Dövüşler de puan verir: galibiyet 2, bitiriş +1, bonus +1, kemer +1. Mağlubiyet ve beraberlik 1 puan.": "Las peleas también dan puntos: victoria 2, finalización +1, bono +1, cinturón +1. Derrota y empate 1 punto.",
  "📅 Bir dövüş döngüsü (kamp + toparlanma) yaklaşık 90-100 gün sürer. Yılda 3-4 kez dövüşürsün; her karar önemli.": "📅 Un ciclo de pelea (campamento + recuperación) dura unos 90-100 días. Peleas 3-4 veces al año; cada decisión cuenta.",
  "Puanı istediğin istatistiğe harcarsın. 50’ye kadar +1 için 1 puan, 70’e kadar 2, 85’e kadar 3, sonrası 4 puan gerekir.": "Gasta los puntos en la estadística que quieras. Hasta 50, +1 cuesta 1 punto; hasta 70, 2; hasta 85, 3; después, 4 puntos.",
  "Kamp sonunda tartıdan önce, dövüş sonrasında ya da Kariyer ekranındaki GELİŞİM sekmesinden harcayabilirsin.": "Puedes gastarlos antes del pesaje al final del campamento, tras una pelea o en la pestaña DESARROLLO de la pantalla de carrera.",
  "Nasıl Oynanır?": "Cómo jugar",
  "1️⃣ Rakip seç. Bölgesel aşamada sen seçersin, büyük organizasyonlarda rakibi organizasyon dayatır.": "1️⃣ Elige rival. En la etapa regional eliges tú; en las grandes promotoras te lo asignan.",
  "2️⃣ Kamp: odak alanı, oyun planı, yoğunluk, kilo verme ve basın toplantısı. Oyun planı rakibin zaafına denk gelirse kafeste büyük avantaj sağlar.": "2️⃣ Campamento: área de enfoque, plan de pelea, intensidad, corte de peso y conferencia de prensa. Un plan que ataque la debilidad del rival da una gran ventaja en la jaula.",
  "3️⃣ Dövüş: her raunt taktik seçersin. Kritik anlarda (rakip sarsıldı, submission yakalandı) hızlı karar verirsin.": "3️⃣ Pelea: elige una táctica cada asalto. En los momentos críticos (rival sacudido, sumisión atrapada) tomas decisiones rápidas.",
  "4️⃣ Sonrası: bonuslar, röportaj, sıralama, kontrat teklifleri ve dövüşler arası olaylar.": "4️⃣ Después: bonos, entrevista, ranking, ofertas de contrato y eventos entre peleas.",
  "🏆 Yol: Amatör → Bölgesel (CFC, Hexagon) → Büyük (PFC, ZEN, VIP) → DWCS veya kısa haber → UCC kemeri.": "🏆 El camino: Amateur → Regional (CFC, Hexagon) → Grande (PFC, ZEN, VIP) → DWCS o aviso corto → cinturón de UCC.",
  "BOŞ YUVA": "RANURA VACÍA",
