  "{0} sokaklarından çıktı; {1} yaşında {2} galibiyete ulaştı, {3} bitiriş.": "Salió de las calles de {0}; {2} victorias y {3} finalizaciones a los {1} años.",
  "HOCAN · {0}": "TU ENTRENADOR · {0}",
  "ANLADIM": "ENTENDIDO",
  "İpuçlarını kapat": "Desactivar consejos",
  "Burası senin köşen": "Esta es tu esquina",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. Aradaki haftalarda mağaza, sosyal medya ve gece hayatı seni bekliyor; ama unutma, her şeyin bir bedeli var.": "Arriba tienes tu dinero, tu salud y tu popularidad. Cuando estés listo, elige rival con “ORGANIZAR PELEA”. En las semanas intermedias te esperan la tienda, las redes y la vida nocturna; pero recuerda, todo tiene un precio.",
  "Gelişim puanları": "Puntos de habilidad",
  "Kamplardan ve dövüşlerden puan kazanırsın, burada istatistiklerine dağıtırsın. 50’den sonra her artış pahalanır; zayıf yönünü kapatmak çoğu zaman daha akıllıcadır.": "Ganas puntos en los campamentos y las peleas y aquí los repartes en tus estadísticas. Por encima de 50 cada punto cuesta más; cubrir tu debilidad suele ser lo más inteligente.",
  "Rakibini seç": "Elige a tu rival",
  "Her rakibin gücü ve zayıf yönü yazıyor. Kolay rakip güvenlidir ama az kazandırır; riskli bir rakibi yenersen sıralamada büyük bir sıçrama yaparsın.": "Cada rival muestra su poder y su debilidad. Un rival fácil es seguro pero da poco; si vences a uno arriesgado darás un gran salto en el ranking.",
  "Kamp başlıyor": "Empieza el campamento",
  "Önce kampın süresini seç. Uzun kamp daha çok geliştirir ama pahalıdır ve yorar. Kamptan önceki boş haftalarda teknik çalışabilir, spar yapabilirsin.": "Primero elige cuánto dura tu campamento. Uno largo te desarrolla más, pero es caro y desgasta. En las semanas libres antes del campamento puedes practicar técnica y hacer sparring.",
  "Oyun planı": "Plan de pelea",
  "Rakibin zayıf yönüne uyan plan, dövüşte etkisini ikiye katlar. Keşif raporuna bak ve planını ona göre seç.": "Un plan que ataca la debilidad del rival duplica su efecto en la pelea. Mira el informe de scouting y elige tu plan.",
  "Burun buruna": "Cara a cara",
  "Tartıdan sonra rakibinle yüz yüze geleceksin. Takındığın tavır onun moralini bozabilir ya da sana pahalıya patlayabilir.": "Tras el pesaje quedarás cara a cara con tu rival. Tu actitud puede hundir su moral o salirte muy cara.",
  "Her raundun başında bir taktik seç, dövüş kendi akar. Rakip sarsıldığında ya da bir submission fırsatında hızlı karar vermen gerekir. Kondisyonunu izle: yorulursan her şey zorlaşır.": "Elige una táctica al inicio de cada asalto y la pelea fluye sola. Cuando tu rival esté sacudido o surja una sumisión, tendrás que decidir rápido. Vigila tu cardio: si te cansas, todo se complica.",
  "Dövüş bitti": "Terminó la pelea",
  "Mikrofon sende: röportajdaki sözlerin popülerliğini etkiler. Kazandığın puanları GELİŞİM sekmesinde harca. Güzel bir galibiyet mi? Paylaş, herkes görsün!": "El micrófono es tuyo: lo que digas en la entrevista afecta tu popularidad. Gasta los puntos ganados en la pestaña DESARROLLO. ¿Una gran victoria? ¡Compártela para que todos la vean!",
  "Google Play’de ücretsiz": "Gratis en Google Play",
