  "{0} mi? Bu kafese değil, kreşe gitmeli.": "¿{0}? Tú deberías ir a la guardería, no a la jaula.",
  "Şu surata bakın: daha önce çok dayak yediği belli.": "Mira esa cara: se nota que te han pegado mucho.",
  "Onun antrenmanlarını izledim. Annem daha sert vuruyor.": "Vi tus entrenamientos. Mi madre pega más fuerte.",
  "Tek yeteneği basın toplantısında uyumamak.": "Tu único talento es no dormirte en las ruedas de prensa.",
  "Ben bu sıkletin kralıyım. Onu ilk rauntta uyutacağım, yazın bir kenara.": "Soy el rey de esta división. Te duermo en el primer asalto, apúntalo.",
  "Bana rakip bulamıyorlar, o yüzden bunu getirdiler.": "No me encuentran rivales, así que me trajeron esto.",
  "Kemeri şimdiden evime astım. Bu maç sadece formalite.": "El cinturón ya cuelga en mi casa. Esta pelea es un trámite.",
  "Benim ısınmam onun bütün kariyeri kadar sürüyor.": "Mi calentamiento dura más que toda tu carrera.",
  "Hahaha! {0} titriyor bakın, ellerine bakın!": "¡Jajaja! {0}, te tiemblan las manos, ¡mírenlas!",
  "Kilo verirken ağladığını duydum. Çok tatlı.": "Dicen que lloras cuando bajas de peso. Qué tierno.",
  "Gözlerime bakamıyor bile. Daha şimdiden kaybetti.": "Ni siquiera puedes mirarme a los ojos. Ya perdiste.",
  "Hocası bile onun yerine utanıyor, şu hâline bakın.": "Hasta tu entrenador se avergüenza por ti, mírate.",
  "Kreş mi? Doğru, cumartesi seni orada bebek gibi uyutacağım.": "¿Guardería? Claro, el sábado te duermo como a un bebé.",
  "Annenle antrenman yapıyorsan bana da numarasını ver, belki bir şey öğrenirim.": "Si entrenas con tu madre, pásame su número, a lo mejor aprendo algo.",
  "Konuş, konuş. Cumartesi gecesi konuşamayacaksın.": "Habla, habla. El sábado por la noche no podrás.",
  "Laflar ucuz. Kafeste görüşürüz.": "Hablar es fácil. Nos vemos en la jaula.",
  "Bir daha ağzını açarsan burada dağıtırım seni!": "¡Abre la boca otra vez y te destrozo aquí mismo!",
  "Kapa çeneni yoksa ben kapatırım!": "¡Cállate o te callo yo!",
