  "Sağlıklı": "Sano",
  "🧠 Ağır darbeler aldın. Beyin hasarı +{0} ({1}/100).": "🧠 Recibiste golpes duros. Daño cerebral +{0} ({1}/100).",
  "🩺 Doktor seni muayeneye çağırıyor. Sonuçlar kariyer ekranında.": "🩺 El médico quiere examinarte. Los resultados están en tu pantalla de carrera.",
  "Nörologa git": "Ir al neurólogo",
  "Ayrıntılı tarama ve tedavi. Hasar -4.": "Pruebas detalladas y tratamiento. Daño -4.",
  "Boş ver, devam": "Olvídalo y sigue",
  "Raporu çekmeceye kaldır. Hiçbir şey değişmez.": "Guarda el informe en un cajón. Nada cambia.",
  "Doktor uyarısı": "Aviso médico",
  "Rutin taramada küçük izler görüldü. \"Henüz endişelenecek bir şey yok, ama sparringde kafaya aldığın darbeleri azaltmalısın.\"": "Un chequeo rutinario mostró pequeñas huellas. \"Aún no hay que preocuparse, pero deberías reducir los golpes a la cabeza en el sparring.\"",
  "Kafa sparringini bırak": "Deja el sparring a la cabeza",
  "Bundan sonra hasar %25 daha az birikir. Canlı sparring keskinliği gider: Hız kalıcı -1.": "A partir de ahora el daño se acumula un 25% menos. Pierdes chispa del sparring real: Velocidad -1 permanente.",
  "Nörolog raporu": "Informe del neurólogo",
  "Tepki sürelerin yavaşlamış, baş ağrıların sık. Doktor ciddi: \"Çenen eskisi gibi değil. Kafeste daha çabuk sarsılacaksın.\"": "Tus reflejos se han ralentizado y los dolores de cabeza son frecuentes. El médico es serio: \"Tu mentón ya no es el de antes. Te sacudirán con más facilidad.\"",
  "8 hafta tam dinlenme": "8 semanas de descanso total",
  "Hasar -5, sağlık tamamen dolar.": "Daño -5, salud al máximo.",
  "Son uyarı": "Último aviso",
  "Doktor gözlerinin içine bakıyor: \"Bir ağır nakavt daha hayatını değiştirebilir. Ailen için düşün.\"": "El médico te mira a los ojos: \"Un nocaut fuerte más podría cambiarte la vida. Piensa en tu familia.\"",
  "Eldivenleri as": "Colgar los guantes",
  "Sağlığın her şeyden önemli. Kariyer burada biter.": "Tu salud es lo primero. Tu carrera termina aquí.",
  "Bir maç daha": "Una pelea más",
  "Riski bilerek devam et.": "Sigue sabiendo el riesgo.",
  "Lisans askıya alındı": "Licencia suspendida",
  "Atletik komisyon tarama sonuçlarını gördü ve dövüş lisansını askıya aldı. Ya emekli olacaksın ya da lisansı başka bir yerden alacaksın.": "La comisión atlética vio tus pruebas y suspendió tu licencia. O te retiras o consigues la licencia en otro lugar.",
  "Onurlu bir veda.": "Una despedida honrosa.",
  "Başka bir eyaletten lisans al": "Sacar la licencia en otro estado",
  "Para ve itibar kaybı. Basın seni eleştirecek: popülerlik -8.": "Cuesta dinero y reputación. La prensa te criticará: popularidad -8.",
  "🧠 Kafa sparringini bıraktın. Daha az hasar alacaksın ama keskinliğin biraz azaldı.": "🧠 Dejaste el sparring a la cabeza. Recibirás menos daño, pero perdiste algo de chispa.",
  "🧠 Nörolog tedavisi iyi geldi. Beyin hasarı {0}/100.": "🧠 El tratamiento del neurólogo ayudó. Daño cerebral {0}/100.",
  "🛌 8 hafta tam dinlendin. Baş ağrıların azaldı. Beyin hasarı {0}/100.": "🛌 Descansaste 8 semanas. Los dolores de cabeza bajaron. Daño cerebral {0}/100.",
  "🧤 Doktorunu dinledin ve eldivenleri astın. Sağlığın için verilmiş en zor karar.": "🧤 Escuchaste a tu médico y colgaste los guantes. La decisión más difícil, por tu salud.",
  "📄 Başka bir eyaletten lisans aldın (${0}). Basın sert: \"Kim durduracak onu?\"": "📄 Conseguiste la licencia en otro estado (${0}). La prensa es dura: \"¿Quién lo va a detener?\"",
  "🩺 Raporu çekmeceye kaldırdın.": "🩺 Guardaste el informe en un cajón.",
  "Doktorunu dinleyip zamanında bıraktı. Yıllar sonra bile hafızası yerinde, çocuklarına bütün maçlarını tek tek anlatıyor.": "Escuchó al médico y lo dejó a tiempo. Años después su memoria sigue intacta y cuenta cada pelea a sus hijos.",
  "Kafeste aldığı darbelerin bedelini emeklilikte ödüyor: konuşması yavaşladı, isimleri unutuyor. Eski rakipleri onu ziyarete geliyor.": "Paga en el retiro el precio de la jaula: habla más lento y olvida nombres. Sus viejos rivales lo visitan.",
  "Sık sık baş ağrısı çekiyor ve bazı günler kelimeleri bulmakta zorlanıyor. Yine de salona gelip gençlere ders veriyor.": "Sufre dolores de cabeza frecuentes y algunos días le cuesta encontrar las palabras. Aun así va al gimnasio a enseñar.",
  "Kariyerin izleri hafif: arada bir baş ağrısı, soğuk havalarda eski nakavtları hatırlatan bir sızı.": "La carrera dejó huellas leves: algún dolor de cabeza y una molestia en los días fríos.",
  "Kafesten sağlıklı çıktı. Zihni berrak, enerjisi yerinde; ikinci bir hayata hazır.": "Salió sano de la jaula. Mente clara, energía intacta; listo para una segunda vida.",
  "Dean Wyatt bizzat aradı: \"Hayranlar seni özledi. Bir ana maç, büyük bir çek. Ne dersin?\"": "Dean Wyatt llamó en persona: \"Los fans te extrañan. Un evento estelar, un gran cheque. ¿Qué dices?\"",
  "VIP MMA servet teklif ediyor: \"Efsanenin dönüşü\" diye bir gece kurmak istiyorlar.": "VIP MMA ofrece una fortuna: quieren montar una noche llamada \"El regreso de la leyenda\".",
  "{0} arıyor: \"Seyircimiz seni bir kez daha görmek istiyor.\"": "{0} llama: \"Nuestro público quiere verte una vez más.\"",
  "🔥 {0} yıl sonra {1} geri dönüyor! {2} ile 2 maçlık kontrat (${3}).": "🔥 ¡Tras {0} años, {1} regresa! Contrato de 2 peleas con {2} (${3}).",
  "🔥 EFSANE GERİ DÖNDÜ! {0}, {1} yıllık aradan sonra kafese galibiyetle döndü.": "🔥 ¡LA LEYENDA HA VUELTO! {0} regresó a la jaula con una victoria tras {1} años.",
  "🔥 DÖNÜŞ ZAFERİ! Yıllar sonra hâlâ buradasın. Popülerlik +10.": "🔥 ¡VICTORIA DEL REGRESO! Años después, sigues aquí. Popularidad +10.",
  "💔 {0} dönüş maçını kaybetti. Seyirci yine de ayakta alkışladı.": "💔 {0} perdió la pelea del regreso. Aun así el público lo ovacionó de pie.",
  "💔 Dönüş planladığın gibi gitmedi. Ama seyirci seni ayakta alkışladı.": "💔 El regreso no salió como planeabas. Pero el público te ovacionó de pie.",
