  "Rakip saldırı hazırlarken başında küçülen bir halka çıkar. Halka ALTIN olunca KAÇ'a bas, sonra hemen vur: kontra vuruşların çift hasar yapar.": "Cuando tu rival prepara un golpe, aparece un aro que se encoge. Cuando se vuelva DORADO, pulsa ESQUIVA y golpea enseguida: los contragolpes hacen el doble.",
  "Vur ve kes": "Golpea y corta",
  "JAB hızlı ve ucuz, DİREKT ve TEKME ağırdır. Rakip hazırlanırken DİREKT ya da TEKME atarsan saldırısını kesersin. Sarı çubuk nefesin: bitince vuruşların zayıflar.": "El JAB es rápido y barato; RECTO y PATADA son pesados. Lanza un RECTO o PATADA durante su preparación para cortarla. La barra amarilla es tu aire: si se agota, tus golpes se debilitan.",
  "İNDİR ile takedown dene; rakip ⬇️ ile dalarsa KAÇ ile sprawl yap. Yerde düğmeler değişir: üstteyken vur ve submission ara, alttayken 🔒 görünce hemen KURTUL.": "Intenta DERRIBAR; si él entra con ⬇️, haz sprawl con ESQUIVA. En el suelo cambian los botones: arriba golpea y busca la sumisión; abajo, ESCAPA en cuanto veas 🔒.",
