  "🏆 Yükseliş Grand Prix'ini kazandın! Organizasyonlar sıraya girdi: profesyonel kapı ardına kadar açık.": "🏆 ¡Ganaste el Grand Prix Ascenso! Las organizaciones hacen fila: la puerta profesional está abierta de par en par.",
  "🥈 Finalde kaybettin ama herkes seni izledi. Profesyonel organizasyonlar seni kadrosunda istiyor!": "🥈 Perdiste la final, pero todos te vieron. ¡Las organizaciones profesionales te quieren en su plantel!",
  "YÜKSELİŞ GRAND PRIX'İ DAVETİ": "INVITACIÓN GRAND PRIX ASCENSO",
  "Profesyonelliğe giden yolda vitrin: 8 amatör, üç maç (çeyrek final, yarı final, final). Kaybeden elenir. Şampiyon {0} ve kupayı alır; şampiyon da finalist de doğrudan profesyonel teklif alır. Davet yalnızca bir kez gelir.": "Tu vitrina rumbo al profesionalismo: 8 amateurs, tres peleas (cuartos, semifinal, final). Quien pierde queda fuera. El campeón se lleva {0} y el trofeo; campeón y finalista reciben ofertas profesionales directas. La invitación llega una sola vez.",
