  "🏛️ Müzene yeni hatıra: {0}": "🏛️ Nuevo recuerdo en tu museo: {0}",
  "Her şeyin başladığı gece. Eldivenler hâlâ terli kokuyor.": "La noche en que todo empezó. Los guantes aún huelen a sudor.",
  "Rakip yere düştüğünde salonun nasıl patladığını hâlâ duyuyorsun.": "Aún oyes cómo estalló el pabellón cuando cayó.",
  "Fotoğrafçı tam o anı yakaladı: rakibin eli minderde, senin yüzünde sakinlik.": "El fotógrafo captó el momento justo: su mano en la lona, calma en tu cara.",
  "Adın ilk kez büyük harflerle bir afişteydi.": "Tu nombre en letras grandes en un cartel por primera vez.",
  "Kocaman karton bir çek. Fotoğrafı annen çerçeveletti.": "Un cheque gigante de cartón. Tu madre enmarcó la foto.",
  "Kartlarda gerideydin. Bu bandajlarla maçı çevirdin.": "Ibas perdiendo en las tarjetas. Con estas vendas le diste la vuelta.",
  "Bahis şirketleri seni yazmamıştı bile. Gazete manşeti duvarında.": "Las casas de apuestas te daban por perdido. El titular está en tu pared.",
  "Doktorlar iki kez kontrol etti. Sen bırakmadın.": "Los médicos te revisaron dos veces. No te rendiste.",
  "Yıllarca süren rekabet. Afişin altında ikinizin de imzası var.": "Años de rivalidad. Ambas firmas están en el cartel.",
  "Kafes dışında başlayan bir hikâye kafeste bitti.": "Una historia que empezó fuera de la jaula terminó dentro.",
  "Altın ilk kez beline değdiğinde ağladın. Kameralar da gördü.": "Lloraste cuando el oro tocó tu cintura. Las cámaras también lo vieron.",
  "Dünyanın en büyük sahnesi. En tepedesin.": "El escenario más grande del mundo. Estás en la cima.",
  "Kemeri almak bir şey, tutmak başka.": "Ganar el cinturón es una cosa; retenerlo, otra.",
  "Üç kez geldiler, üç kez gönderdin.": "Vinieron tres veces y tres veces los despachaste.",
