  "Annenin bahçesinde çekilmiş bir fotoğraf. Arkasında “Her zaman buradayız.” yazıyor.": "Una foto en el jardín de tu madre. Al dorso: “Siempre estamos aquí.”",
  "Gün doğumunda yüzlerce balon. Hayatında ilk kez kafan bu kadar sessizdi.": "Cientos de globos al amanecer. Por primera vez tu cabeza estuvo en silencio.",
  "Açık büfeden bir tabak. Arkasına antrenörün “Bunu görmedim.” yazmış.": "Un plato del bufé. Tu entrenador escribió detrás: “Yo no he visto esto.”",
  "Sörf tahtasıyla kumsalda. İlk dalgada düştün, onuncuda ayaktaydın.": "En la playa con una tabla. Caíste en la primera ola y te pusiste de pie en la décima.",
  "Bir gökdelenin tepesinden şehir. Ünlülerle çekilmiş fotoğraflar telefonunda.": "La ciudad desde lo alto de un rascacielos. Tu móvil lleno de fotos con famosos.",
  "Su üstü villanın terası. İki hafta boyunca telefona bakmadın.": "La terraza de una villa sobre el agua. No miraste el móvil en dos semanas.",
  "Yarış pistinin kenarında bir yat. Kimin partisi olduğunu hâlâ bilmiyorsun.": "Un yate junto al circuito. Aún no sabes de quién era la fiesta.",
