  "Kızın {0} dünyaya geldi": "Nace tu hija {0}",
  "Oğlun {0} dünyaya geldi": "Nace tu hijo {0}",
  "Hayatının en güzel günü": "El mejor día de tu vida",
  "👣 İlk Adım": "👣 Primeros Pasos",
  "{0} salonun ortasında, kanepeden sana doğru üç adım attı ve kucağına düştü. Telefon kayıttaydı.": "En medio del salón, {0} dio tres pasos desde el sofá hacia ti y cayó en tus brazos. El móvil estaba grabando.",
  "Videoyu paylaş": "Compartir el vídeo",
  "Aile arasında kalsın": "Que quede en familia",
  "Video bir gecede milyonlara ulaştı. Popülerlik +1, +{0} takipçi.": "El vídeo llegó a millones en una noche. Popularidad +1, +{0} seguidores.",
  "Bu an yalnızca sizin. Videoyu her antrenmandan önce izliyorsun. Motivasyon +1.": "Este momento es solo vuestro. Ves el vídeo antes de cada entrenamiento. Motivación +1.",
  "{0} ilk adımlarını atıyor": "{0} dando sus primeros pasos",
  "🗣️ İlk Kelime": "🗣️ Primera Palabra",
  "Herkes “{0}” demesini bekliyordu. {1} televizyonda maçını görünce bağırdı: “Kafes!”": "Todos esperaban “{0}”. Al ver tu pelea en la tele, {1} gritó: “¡Jaula!”",
  "anne": "mamá",
  "baba": "papá",
  "Gülmekten yerlere yat": "Morirte de risa",
  "Bir de “kemer” demeyi öğret": "Enseñarle también “cinturón”",
  "Bütün aile gözyaşları içinde güldü. Motivasyon +1.": "Toda la familia lloró de risa. Motivación +1.",
  "İkinci kelime de geldi: “Kemer!” Motivasyon +1.": "Llegó la segunda palabra: “¡Cinturón!” Motivación +1.",
  "{0} ve ilk kelimesi: “Kafes!”": "{0} y su primera palabra: “¡Jaula!”",
  "🏟️ Tribünde İlk Kez": "🏟️ Primera Vez en la Grada",
  "{0} artık üç yaşında ve bir sonraki maçını tribünden izlemek istiyor. Kulaklığı ve minik formasını şimdiden hazırlamış.": "{0} ya tiene tres años y quiere ver tu próxima pelea desde la grada. Los cascos y la camisetita ya están listos.",
  "Ön sıraya bilet al": "Comprar entrada de primera fila",
  "Daha küçük, evden izlesin": "Aún es pequeño, que lo vea en casa",
  "Kafese yürürken onu ön sırada gördün. Kulaklıkları kafasından büyüktü. Motivasyon +2, popülerlik +1.": "Camino de la jaula lo viste en primera fila. Los cascos eran más grandes que su cabeza. Motivación +2, popularidad +1.",
  "{0} maçı evden izledi ve televizyonun önünde senin hareketlerini taklit etti. Motivasyon +1.": "{0} lo vio desde casa imitando tus movimientos frente a la tele. Motivación +1.",
  "Tribündeki en küçük taraftar: {0}": "El aficionado más pequeño: {0}",
  "🎒 Okulun İlk Günü": "🎒 Primer Día de Colegio",
  "{0} bugün okula başlıyor. Aynı sabah sponsorunun basın toplantısı var.": "{0} empieza el colegio hoy. La rueda de prensa de tu patrocinador es esa misma mañana.",
  "Okula sen götür": "Llevarlo tú al colegio",
  "Basın toplantısına git": "Ir a la rueda de prensa",
  "Kapıda elini bırakmak istemedi. Sonra arkasına bakmadan koştu. Motivasyon +2.": "En la puerta no quería soltarte la mano. Luego corrió sin mirar atrás. Motivación +2.",
  "Toplantı iyi geçti ama akşam {0} sana bütün günü tek tek anlattı ve sen orada değildin. Popülerlik +2, motivasyon -1.": "La rueda fue bien, pero por la noche {0} te contó todo el día y tú no estuviste. Popularidad +2, motivación -1.",
  "{0} okulun ilk gününde": "{0} en su primer día de colegio",
  "🥋 İlk Kuşak": "🥋 Primer Cinturón",
  "{0} çocuk judo kursunda ilk kuşağını aldı. Törende hocasına değil, tribündeki sana dönüp eğildi.": "{0} consiguió su primer cinturón en judo infantil. En la ceremonia se inclinó hacia ti en la grada, no hacia el maestro.",
  "Kuşağını sen bağla": "Atarle tú el cinturón",
  "Kenardan alkışla": "Aplaudir desde un lado",
  "Kuşağı bağlarken ellerin titredi. Hiçbir kemer böyle hissettirmemişti. Motivasyon +2.": "Te temblaban las manos al atarlo. Ningún cinturón te había hecho sentir así. Motivación +2.",
  "Salonun en yüksek alkışı seninkiydi. Motivasyon +2.": "Tu aplauso fue el más fuerte de la sala. Motivación +2.",
  "{0} ilk kuşağıyla": "{0} con su primer cinturón",
