  "🌍 {0}, {1} sahnesinde zorlanıyor.": "🌍 {0} lo está pasando mal en {1}.",
  "🌍 {0}, {1} kemerini kaybetti.": "🌍 {0} perdió el cinturón de {1}.",
  "Albümündeki kartı altına yükseldi.": "Su carta en tu álbum ahora es de oro.",
  "Rıza Hoca": "Maestro Rıza",
