  "Kopma noktasında": "A punto de romperse",
  "🤝 {0} ile aranız çok iyi: köşedeki her sözü tam zamanında geliyor (IQ +1).": "🤝 Con {0} hay sintonía total: cada consejo llega justo a tiempo (IQ +1).",
  "🧊 {0} ile aranız soğuk: köşede konuşmalar kısa ve gergin (IQ -1).": "🧊 Con {0} hay frialdad: en la esquina se habla poco y con tensión (IQ -1).",
  "{0}: “Seninle gurur duyuyorum. Şimdi git ve al şunu.”": "{0}: “Estoy orgulloso de ti. Ahora ve y tómalo.”",
  "{0} yalnızca “Planı biliyorsun.” dedi. Sesi soğuktu.": "{0} solo dijo: “Ya sabes el plan.” Su voz sonó fría.",
  "💢 Hocanla Kriz": "💢 Crisis con tu Entrenador",
  "{0} antrenmandan sonra seni kenara çekti: “Beni dinlemiyorsun. Böyle devam edeceksek yollarımızı ayıralım.”": "Tras el entreno, {0} te apartó: “No me escuchas. Si seguimos así, separemos caminos.”",
  "Özür dile, yeniden başlayalım": "Pedir perdón y empezar de nuevo",
  "Maaşına zam yap ({0})": "Subirle el sueldo ({0})",
  "Yollarınızı ayırın": "Separar caminos",
  "Gururunu yuttun. {0} başını salladı: “Yarın sabah altıda.” Bağ toparlanıyor, motivasyon -1.": "Te tragaste el orgullo. {0} asintió: “Mañana a las seis.” El vínculo se recupera, motivación -1.",
  "Zam iyi geldi ama asıl önemli olan oturup konuşmanızdı. Bağ güçlendi.": "El aumento ayudó, pero lo importante fue sentarse a hablar. El vínculo se fortaleció.",
  "{0} ile yollarınız ayrıldı. Yeni hocan {1}. Sıfırdan bir güven kurmanız gerekecek. Motivasyon -1.": "Te separaste de {0}. Tu nuevo entrenador es {1}. Tendréis que construir la confianza desde cero. Motivación -1.",
  "🫂 Bir Baba Gibi": "🫂 Como un Padre",
  "Gece salonda yalnız kaldınız. {0} eski bir fotoğraf çıkardı: ilk antrenmanın, eldivenler elinden büyük. “O gün kapıdan girdiğinde ne olacağını biliyordum,” dedi.": "De noche, solos en el gimnasio, {0} sacó una foto vieja: tu primer entreno, los guantes más grandes que tus manos. “El día que entraste por esa puerta, lo supe”, dijo.",
  "Sarıl": "Abrazarlo",
  "“Her şeyi sana borçluyum.”": "“Te lo debo todo.”",
  "{0} ile ilk antrenman fotoğrafı": "Foto del primer entreno con {0}",
  "Eldivenler elinden büyük. Arkasında hocanın el yazısı: “Bir gün.”": "Guantes más grandes que tus manos. Detrás, con la letra de tu entrenador: “Algún día.”",
  "Uzun süre konuşmadınız. Gerek yoktu. Motivasyon +2.": "Estuvisteis mucho rato sin hablar. No hacía falta. Motivación +2.",
  "“Hayır,” dedi, “her şeyi kendine borçlusun. Ben sadece kapıyı açtım.” Motivasyon +2.": "“No”, dijo, “te lo debes todo a ti. Yo solo abrí la puerta.” Motivación +2.",
  "📨 Rakip Kampın Teklifi": "📨 Oferta de un Campamento Rival",
  "Büyük bir salon {0} hocana baş antrenörlük teklif etmiş, maaşı iki katı. Sana söylemedi; sen başkasından duydun.": "Un gran gimnasio le ofreció a tu entrenador {0} ser jefe técnico con el doble de sueldo. No te lo dijo; te enteraste por otro.",
  "Ona zam yap ve kalmasını iste ({0})": "Subirle el sueldo y pedirle que se quede ({0})",
  "Onu tebrik et, gitmesine izin ver": "Felicitarlo y dejarlo ir",
  "Sessiz kal, kararı ona bırak": "Callar y dejar que decida él",
  "{0} teklifi reddetti: “Benim dövüşçüm burada.” Bağ çok güçlendi.": "{0} lo rechazó: “Mi luchador está aquí.” El vínculo es mucho más fuerte.",
  "{0} gözleri dolu gitti, giderken seni yeni hocan {1} ile tanıştırdı. Motivasyon +1.": "{0} se fue emocionado y, al salir, te presentó a tu nuevo entrenador {1}. Motivación +1.",
  "{0} kaldı. “Sana sormadan karar vermem gerekirdi, ama burası benim evim,” dedi.": "{0} se quedó. “Debería haberlo decidido sin preguntarte, pero este es mi hogar”, dijo.",
  "{0} teklifi kabul etti. Yeni hocan {1}.": "{0} aceptó la oferta. Tu nuevo entrenador es {1}.",
  "🏥 Hocanın Sağlığı": "🏥 La Salud de tu Entrenador",
  "{0} birkaç haftadır öksürüyordu. Doktorlar dinlenmesini söyledi ama o kampı bırakmak istemiyor.": "{0} lleva semanas tosiendo. Los médicos le pidieron descanso, pero no quiere dejar el campamento.",
  "Zorla tatile gönder, kampı asistan yönetsin": "Obligarlo a descansar; que el asistente lleve el campamento",
  "Onun kararına saygı duy": "Respetar su decisión",
  "Önce kızdı, sonra teşekkür etti. Bir ay sonra eskisinden dinç döndü. Bağ güçlendi.": "Primero se enfadó, luego te dio las gracias. Un mes después volvió más fuerte que nunca. El vínculo creció.",
  "Kampı yönetti ama her gece onu merak ettin. Motivasyon -1.": "Dirigió el campamento, pero te preocupaste por él cada noche. Motivación -1.",
  "🕊️ Hocanın Vedası": "🕊️ La Despedida de tu Entrenador",
  "{0} seni salonun ortasına çağırdı: “Yaşlandım evlat. Sana öğretebileceğim her şeyi öğrettim.” Yerine kendi asistanını önerdi.": "{0} te llamó al centro del gimnasio: “Me hago mayor, chaval. Te he enseñado todo lo que sé.” Propuso a su asistente como relevo.",
  "Son bir antrenman yapın": "Hacer un último entreno",
  "Veda yemeği düzenle": "Organizar una cena de despedida",
  "{0} ile son fotoğraf": "Última foto con {0}",
  "Son antrenmanın sonunda minderde yan yana": "Uno junto al otro en el tatami tras el último entreno",
  "Veda yemeğinde, bütün salon bir arada": "En la cena de despedida, todo el gimnasio junto",
  "Asistan {0}": "Asistente {0}",
