  "Analist ekibi rakibinin son üç maçını kare kare çözdü. Hazırlıklısın.": "Los analistas desglosaron fotograma a fotograma las tres últimas peleas de tu rival. Estás preparado.",
  "Zarfı aldın. İçindekilerin ne kadar doğru olduğunu kafeste göreceksin.": "Cogiste el sobre. En la jaula sabrás si era cierto.",
