  "🕵️ Söylenti blöftü, kanmadın. Aferin.": "🕵️ Era un farol y no picaste. Bien hecho.",
  "🕵️ {0} kiloyu zor vermiş; tempolu kampın meyvesini verecek (kondisyon +2).": "🕵️ {0} dio el peso a duras penas; tu campamento intenso dará frutos (cardio +2).",
  "🕵️ {0} formda geldi. Fazla tempolu kamp seni biraz yordu (kondisyon -1).": "🕵️ {0} llegó en forma. El campamento tan intenso te cansó un poco (cardio -1).",
