  "{0}: 15 saniyelik bir mini oyun. İyi oynarsan bütün kamp daha verimli geçer, sakatlık riski düşer.": "{0}: un minijuego de 15 segundos. Si lo haces bien, todo el campamento rinde más y baja el riesgo de lesión.",
