  "Kamp hazır. Haftalar kendiliğinden akacak; bir karar gerektiğinde duracak.": "El campamento está listo. Las semanas avanzarán solas y se detendrán cuando haga falta decidir.",
  "Sparda sert bir darbe aldın; kaburgaların sızlıyor. {0} kararı sana bırakıyor.": "Recibiste un golpe duro en el sparring; te duelen las costillas. {0} te deja decidir.",
