  "Diyetisyen tartıyı erken düşünmeni öneriyor: şimdiden kalori kesersen son 48 saat kolaylaşır.": "Tu nutricionista sugiere pensar ya en el pesaje: si recortas calorías ahora, las últimas 48 horas serán más fáciles.",
  "Diyete şimdi başla": "Empezar la dieta ya",
